export var dbset = [];

var dbbtn = `<div id="dbbutton" class="textshirt dbbutton" style="top: 91.3769%; left: 95.4652%; width: 36px; height: 36px;"><div id="dbbutton2" class="dbbutton textshirt circleshirt" style="height: 36px; width: 36px; top: 91.3769%; left: 95.4652%; background-color: rgb(255, 255, 255); border-color: rgb(255, 255, 255); color: rgb(255, 255, 255);"></div><div id="dbbutton3" class="dbbutton textshirt circleshirt" style="height: 22px; width: 22px; top: 92.4896%; left: 96.0907%;"></div></div>`;

//to adjust
export const dbtitle = 'monoprompt';
const defaultspeed = 25;
const transws = ' wspeed_10';
const drabindex = 'monoprompt';

const bimgpath = storyline.jsonUrl+'./drawboard/bimg/mybeachhousesunset.jpg';
var dbbg =`<div id="dbbackg" class="textshirt imageshirt" style="left: -3px; top: -91px; width: 1280px; height: 853px;"><img src="`+bimgpath+`"></div>`;
